INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7587930, 1221773, 156466, '<td valign="top">God knows I don''t want to have to put this together, but the lack of symmetrical spacing at the top is what kept you out of my top 3. It''s the little things. Still gave you a 7.</td>', 'God knows I don''t want to have to put this together, but the lack of symmetrical spacing at the top is what kept you out of my top 3. It''s the little things. Still gave you a 7.', '2018-08-01 06:51:59.000000', NULL, 1),
(7587931, 1221782, 156466, '<td valign="top">There''s almost too much here. No, there is too much here. I get what you''re going for with a complete circle but I''m thinking that if you simply gave me half of that in a wider spray it would have had more impact.</td>', 'There''s almost too much here. No, there is too much here. I get what you''re going for with a complete circle but I''m thinking that if you simply gave me half of that in a wider spray it would have had more impact.', '2018-08-01 06:54:54.000000', NULL, 1),
(7587932, 1222264, 156466, '<td valign="top">Watch the saturation slider.</td>', 'Watch the saturation slider.', '2018-08-01 06:55:29.000000', NULL, 1),
(7587933, 1221299, 113156, '<td valign="top">Ying yang can. Surprising.</td>', 'Ying yang can. Surprising.', '2018-08-01 06:56:14.000000', NULL, 1),
(7587934, 1221442, 156466, '<td valign="top">Might have liked a tighter crop and perhaps something more horizontal than square (rotated left a bit). Still very creative. Bumping.</td>', 'Might have liked a tighter crop and perhaps something more horizontal than square (rotated left a bit). Still very creative. Bumping.', '2018-08-01 06:57:30.000000', NULL, 1),
(7587937, 1222070, 156466, '<td valign="top">How could you not call this "q-bert"?! <br/> <br/>Returning to comment some more, I think what kept me from giving this higher than the 6 I gave it was the narrow focus plane. Had managed to get some ends fully in focus and others not (or all of them in focus) it may have worked better for me but the transition from in-to-out or out-to-in on individual ends is distracting.</td>', 'How could you not call this "q-bert"?!  Returning to comment some more, I think what kept me from giving this higher than the 6 I gave it was the narrow focus plane. Had managed to get some ends fully in focus and others not (or all of them in focus) it may have worked better for me but the transition from in-to-out or out-to-in on individual ends is distracting.', '2018-08-01 07:00:51.000000', NULL, 1),
(7587938, 1222272, 156466, '<td valign="top">Thank you for resisting oversaturating this, but the soft low key lighting just doesn''t work for me. Vertical crop hurts it in the voting presentation mode as well.</td>', 'Thank you for resisting oversaturating this, but the soft low key lighting just doesn''t work for me. Vertical crop hurts it in the voting presentation mode as well.', '2018-08-01 07:04:26.000000', NULL, 1),
